            pub inline fn getId(_subsurface: *Subsurface) u32 {
                return @as(*server.wl.Resource, @ptrCast(_subsurface)).getId();
            }
            pub inline fn getVersion(_subsurface: *Subsurface) u32 {
                return @as(*server.wl.Resource, @ptrCast(_subsurface)).getVersion();
            }
            pub inline fn postNoMemory(_subsurface: *Subsurface) void {
