            pub inline fn setHandler(
                _window_v1: *WindowV1,
                comptime T: type,
                handle_request: *const fn (_window_v1: *WindowV1, request: Request, data: T) void,
                comptime handle_destroy: ?fn (_window_v1: *WindowV1, data: T) void,
                _data: T,
            ) void {
                const _resource: *server.wl.Resource = @ptrCast(_window_v1);
                _resource.setDispatcher(
                    common.Dispatcher(WindowV1, T).dispatcher,
                    handle_request,
                    @ptrFromInt(@intFromPtr(_data)),
                    if (handle_destroy) |_handler| struct {
                        fn _wrapper(__resource: *server.wl.Resource) callconv(.c) void {
                            _handler(
                                @as(*WindowV1, @ptrCast(__resource)),
                                @as(T, @ptrCast(@alignCast(__resource.getUserData()))),
                            );
                        }
                    }._wrapper else null,
                );
            }
