            /// must be strictly less than or equal to the max_width/max_height.
            ///
            /// This event will be followed by a manage_start event after all other new
            /// state has been sent by the server.
            pub fn sendDimensionsHint(_window_v1: *WindowV1, _min_width: i32, _min_height: i32, _max_width: i32, _max_height: i32) void {
                const _resource: *server.wl.Resource = @ptrCast(_window_v1);
                var _args = [_]common.Argument{
                    .{ .i = _min_width },
                    .{ .i = _min_height },
                    .{ .i = _max_width },
                    .{ .i = _max_height },
                };
                _resource.postEvent(1, &_args);
            }
            pub const dimensions_hint_since_version = 1;

            /// This event indicates the dimensions of the window in the compositor's
            /// logical coordinate space. The width and height must be strictly greater
            /// than zero.
